const ADBLOCK_DEFAULT_SETTINGS = {
    mode: 'ideal',
    showBlockedCount: true,
    autoRefreshOnModeChange: false,
    strictBlock: false,
    developerMode: false
};

function normalizeAdblockMode(mode) {
    const value = String(mode || '').trim().toLowerCase();
    if (value === 'basic' || value === 'aggressive') return value;
    return 'ideal';
}

function normalizeWebStartupLazyDelayMs(value) {
    const num = Number(value);
    return WEB_STARTUP_LAZY_DELAY_OPTIONS.includes(num) ? num : WEB_STARTUP_LAZY_DELAY_DEFAULT_MS;
}

function ensureAdblockSettings() {
    if (!state.settings || typeof state.settings !== 'object') state.settings = {};
    if (!state.settings.adblock || typeof state.settings.adblock !== 'object') {
        state.settings.adblock = { ...ADBLOCK_DEFAULT_SETTINGS };
        return state.settings.adblock;
    }

    state.settings.adblock.mode = normalizeAdblockMode(
        state.settings.adblock.mode || ADBLOCK_DEFAULT_SETTINGS.mode
    );
    if (typeof state.settings.adblock.showBlockedCount !== 'boolean') {
        state.settings.adblock.showBlockedCount = ADBLOCK_DEFAULT_SETTINGS.showBlockedCount;
    }
    if (typeof state.settings.adblock.autoRefreshOnModeChange !== 'boolean') {
        state.settings.adblock.autoRefreshOnModeChange = ADBLOCK_DEFAULT_SETTINGS.autoRefreshOnModeChange;
    }
    if (typeof state.settings.adblock.strictBlock !== 'boolean') {
        state.settings.adblock.strictBlock = ADBLOCK_DEFAULT_SETTINGS.strictBlock;
    }
    if (typeof state.settings.adblock.developerMode !== 'boolean') {
        state.settings.adblock.developerMode = ADBLOCK_DEFAULT_SETTINGS.developerMode;
    }

    return state.settings.adblock;
}

function getAdblockBridgeConfig() {
    const adblock = ensureAdblockSettings();
    return {
        mode: normalizeAdblockMode(adblock.mode),
        autoReload: !!adblock.autoRefreshOnModeChange,
        showBlockedCount: !!adblock.showBlockedCount,
        strictBlock: !!adblock.strictBlock,
        developerMode: !!adblock.developerMode
    };
}

function getAdblockWebModeProfile() {
    const packagedLinuxSafeMode = isPackagedLinuxRuntimeRenderer() && ensureAdblockSettings().developerMode !== true;
    const mode = normalizeAdblockMode(ensureAdblockSettings().mode);

    if (packagedLinuxSafeMode) {
        // Paketli Linux'ta webview donmalarını azaltmak için daha hafif tarama profili.
        // Özellikle DOM taraması ve sık tick döngüsü yavaş cihazlarda ana süreci kilitleyebiliyor.
        if (mode === 'aggressive') {
            return {
                tickIntervalMs: 120,
                uiScrubLevel: 1,
                deepSponsoredScan: false,
                adSignalLevel: 1,
                forceSeekAds: true
            };
        }
        if (mode === 'basic') {
            return {
                tickIntervalMs: 360,
                uiScrubLevel: 0,
                deepSponsoredScan: false,
                adSignalLevel: 0,
                forceSeekAds: false
            };
        }
        return {
            tickIntervalMs: 180,
            uiScrubLevel: 0,
            deepSponsoredScan: false,
            adSignalLevel: 1,
            forceSeekAds: false
        };
    }

    if (mode === 'basic') {
        return {
            tickIntervalMs: 350,
            uiScrubLevel: 0,
            deepSponsoredScan: false,
            adSignalLevel: 0,
            forceSeekAds: false
        };
    }
    if (mode === 'aggressive') {
        return {
            tickIntervalMs: 55,
            uiScrubLevel: 2,
            deepSponsoredScan: true,
            adSignalLevel: 2,
            forceSeekAds: true
        };
    }
    return {
        tickIntervalMs: 75,
        uiScrubLevel: 1,
        deepSponsoredScan: true,
        adSignalLevel: 2,
        forceSeekAds: true
    };
}

async function applyAdblockRuntimeConfig() {
    try {
        await window.aurivo?.adblock?.setConfig?.(getAdblockBridgeConfig());
    } catch (e) {
        console.warn('[ADBLOCK] setConfig error:', e?.message || e);
    }
}

