function ensureMainShellVisible() {
    if (IS_SETTINGS_DOCUMENT) return;
    try {
        const shell = document.querySelector('.app-container');
        if (shell) {
            shell.classList.remove('hidden');
            shell.style.display = 'flex';
        }
        const mustShowSelectors = [
            '.sidebar',
            '.left-panel',
            '.main-content',
            '.nav-bar',
            '.content-stack'
        ];
        for (const selector of mustShowSelectors) {
            const el = document.querySelector(selector);
            if (!el) continue;
            el.classList.remove('hidden');
            el.style.removeProperty('display');
            el.style.removeProperty('visibility');
            el.style.removeProperty('opacity');
        }
        const overlays = document.querySelectorAll('.modal-overlay, .web-loading-overlay');
        overlays.forEach((el) => {
            if (!el) return;
            el.classList.add('hidden');
        });
    } catch {
        // yoksay
    }
}

document.addEventListener('DOMContentLoaded', async () => {
    cacheElements();
    initAppUpdateUi().catch(() => {});
    window.aurivo?.onOpenMediaFiles?.((paths) => {
        enqueueExternalMediaOpen(paths).catch((e) => {
            console.warn('[OPEN_MEDIA] live open error:', e?.message || e);
        });
    });
    window.addEventListener('storage', (event) => {
        if (event.key === 'aurivo_ui_sfx_lights_enabled') {
            applySfxLightsShadowState(event.newValue !== '0');
            return;
        }
        if (event.key === 'aurivo_ui_slider_fx_enabled') {
            applySliderFxShadowState(event.newValue !== '0');
        }
    });
    appearanceSyncChannel?.addEventListener('message', (event) => {
        const type = String(event?.data?.type || '').trim().toLowerCase();
        if (type === 'sfx-lights') {
            applySfxLightsShadowState(event?.data?.enabled !== false);
            return;
        }
        if (type === 'slider-fx') {
            applySliderFxShadowState(event?.data?.enabled !== false);
        }
    });
    if (AURIVO_PERF_MONITOR_ENABLED) {
        PerfMonitor.start(5000);
    }
    bindStandaloneSettingsDirtyTracking();
    installStandaloneSettingsLifecycleHooks();
    window.aurivo?.onSettingsReload?.(async (nextSettings) => {
        if (!nextSettings || typeof nextSettings !== 'object') return;
        const prevLibrarySignature = getLibrarySettingsSyncSignature(state.settings);
        const prevAdblockSnapshot = {
            mode: normalizeAdblockMode(state.settings?.adblock?.mode),
            autoRefreshOnModeChange: !!state.settings?.adblock?.autoRefreshOnModeChange,
            strictBlock: !!state.settings?.adblock?.strictBlock,
            developerMode: !!state.settings?.adblock?.developerMode
        };
        state.settings = nextSettings;
        if (Date.now() < suppressSettingsReloadUiUntil) {
            return;
        }
        const activeSettingsTab = getActiveSettingsTabName() || STANDALONE_SETTINGS_DEFAULT_TAB || 'playback';
        await loadSettings();
        // Ayarlar farklı pencereden kaydedildiğinde ana pencerede görünümü anında uygula.
        applyAppearanceSettingsToRuntime();
        applySecuritySettingsToRuntime();
        applyWebUiClasses();
        applyWebExperienceMode();
        await syncLibraryWatchState();
        const nextLibrarySignature = getLibrarySettingsSyncSignature(state.settings);
        if (prevLibrarySignature !== nextLibrarySignature) {
            await refreshMainLibraryFromSettingsReload();
        }
        if (isStandaloneSettingsMode() || isPageVisible(elements.settingsPage)) {
            loadSettingsToUI();
            activateSettingsTab(activeSettingsTab);
        }
        const nextAdblockSnapshot = {
            mode: normalizeAdblockMode(state.settings?.adblock?.mode),
            autoRefreshOnModeChange: !!state.settings?.adblock?.autoRefreshOnModeChange,
            strictBlock: !!state.settings?.adblock?.strictBlock,
            developerMode: !!state.settings?.adblock?.developerMode
        };
        const adblockModeChanged = prevAdblockSnapshot.mode !== nextAdblockSnapshot.mode;
        const adblockRuntimeChanged =
            adblockModeChanged ||
            prevAdblockSnapshot.strictBlock !== nextAdblockSnapshot.strictBlock ||
            prevAdblockSnapshot.developerMode !== nextAdblockSnapshot.developerMode;
        const isWebActive = state.currentPage === 'web' || state.activeMedia === 'web';
        if (adblockRuntimeChanged && nextAdblockSnapshot.autoRefreshOnModeChange && isWebActive && elements.webView) {
            reloadWebViewForAdblock('settings:reloaded', {
                prevMode: prevAdblockSnapshot.mode,
                nextMode: nextAdblockSnapshot.mode,
                strictBlock: nextAdblockSnapshot.strictBlock,
                developerMode: nextAdblockSnapshot.developerMode
            });
        }
        if (state.currentPage === 'web' || state.activeMedia === 'web' || state.currentPage === 'video' || state.activeMedia === 'video') {
            scheduleApplyWebDaliEngine('settings-reload', 120);
        }
    });
    window.aurivo?.onScopedSfxLiveParam?.((payload) => {
        try {
            applyScopedSfxLiveParam(payload);
        } catch {
            // yoksay
        }
    });
    window.aurivo?.onSettingsNavigate?.(({ tab }) => {
        if (!isStandaloneSettingsMode()) return;
        const nextTab = String(tab || '').trim().toLowerCase() || 'playback';
        loadSettingsToUI();
        activateSettingsTab(nextTab);
    });
    window.aurivo?.onSettingsStandaloneMode?.(({ tab }) => {
        enterStandaloneSettingsMode(String(tab || 'playback').trim().toLowerCase() || 'playback').catch((e) => {
            console.error('[SETTINGS] standalone enter error:', e);
        });
    });
    // "Dosyalar" sekmesini kaldır: sadece Video / Müzik / Web kalsın.
    try {
        const filesTabBtn = document.querySelector('.sidebar-btn[data-page="files"]');
        if (filesTabBtn) filesTabBtn.remove();
    } catch {
        // yoksay
    }
    await initializeI18n();

    if (isStandaloneSettingsMode()) {
        try {
            state.specialPaths = await window.aurivo?.getSpecialPaths?.();
        } catch {
            state.specialPaths = null;
        }
        setupStandaloneSettingsEventListeners();
        await enterStandaloneSettingsMode(STANDALONE_ARG_TAB || STANDALONE_SETTINGS_DEFAULT_TAB || 'playback');
        ensureMainShellVisible();
        resumeSettingsBackgroundWork();
        return;
    }

    // Oynatıcı çubuğu görünürlüğünü kontrol et
    const playerBar = document.getElementById('playerBar');
    if (playerBar) {
        playerBar.classList.remove('hidden');
        playerBar.style.display = 'flex';
        console.log('Player bar görünürlük kontrolü yapıldı');
    }

    try {
        state.specialPaths = await window.aurivo?.getSpecialPaths?.();
        console.log('[PATHS] special paths:', state.specialPaths);
    } catch (e) {
        console.warn('[PATHS] getSpecialPaths failed:', e?.message || e);
        state.specialPaths = null;
    }

    await loadSettings();
    applyWebExperienceMode({ forceSwitch: false });
    // C++ Ses Motoru kontrolü (ayarlar yüklendikten sonra)
    await checkNativeAudio();
    if (getLibraryStartupBehavior().restoreLastPlaylist) {
        await loadPlaylist();
    } else {
        state.playlist = [];
        renderPlaylist();
    }
    setupEventListeners();
    setupPulseQuickListeners();
    setupUtilityWindowIndicators();
    window.addEventListener('beforeunload', () => {
        try {
            rememberPlaybackStartupState({ persist: true });
        } catch {
            // yoksay
        }
        try {
            if (typeof fsWindowFullscreenUnsubscribe === 'function') {
                fsWindowFullscreenUnsubscribe();
            }
        } catch {
            // yoksay
        }
    });
    restoreLastMainSection();
    preloadLastWebPlatformOnStartup();
    // Son kapatılan sekme geri yüklendikten sonra ana kabuğu göster:
    // açılışta anlık "yanlış sekme" parlamasını engeller.
    ensureMainShellVisible();
    await restoreLibraryStartupState();
    const openedByStartupMedia = await enqueueExternalMediaOpen(
        await window.aurivo?.app?.consumePendingOpenMediaFiles?.() || []
    );
    if (!openedByStartupMedia) {
        await restorePlaybackStartupState();
    }
    window.aurivo?.app?.notifyMediaOpenReady?.();
    // Başlangıçta UI'yı hızlı göstermek için ağır kütüphane taramasını gecikmeli başlat.
    // İlk açılışta CPU sıçramasını ve takılma hissini azaltır.
    scheduleStartupLibraryScan();
    await syncLibraryWatchState();
    applyWebUiClasses();
    setupVisualizer();
    initializeRainbowSliders();

    try {
        if (elements.libraryActionsAudio) elements.libraryActionsAudio.classList.toggle('hidden', state.mediaFilter !== 'audio');
        if (elements.libraryActionsVideo) elements.libraryActionsVideo.classList.toggle('hidden', state.mediaFilter !== 'video');
        if (elements.libraryActionsImage) elements.libraryActionsImage.classList.toggle('hidden', state.mediaFilter !== 'image');
        syncLibrarySurfaceControlsUi();
    } catch {
        // yoksay
    }

    console.log('Aurivo Player başlatıldı');
    if (useNativeAudio) {
        console.log('🎵 C++ BASS Audio Engine aktif');
    } else {
        console.log('🎵 HTML5 Audio kullanılıyor');
    }
});

async function initializeI18n() {
    try {
        if (window.i18n && typeof window.i18n.init === 'function') {
            const lang = await window.i18n.init();
            try {
                document.title = await window.i18n.t('app.title');
            } catch {
                // yoksay
            }

            if (elements.languageSelect) {
                elements.languageSelect.value = lang || elements.languageSelect.value;
                hideRestartHint();
                if (!elements.languageSelect.dataset.listenerAttached) {
                    elements.languageSelect.dataset.listenerAttached = 'true';
                    elements.languageSelect.addEventListener('change', (e) => {
                        const next = String(e?.target?.value || '').trim();
                        if (!next) return;
            const currentLang = String(
                window.i18n?.getLanguage?.()
                || state.settings?.ui?.language
                || state.settings?.lang
                || ''
            ).trim();
                        if (next && currentLang && next !== currentLang) {
                            showRestartHint();
                        } else {
                            hideRestartHint();
                        }
                    });
                }
            }
            updatePulseQuickModeUi();
        }
    } catch (e) {
        console.warn('[I18N] init failed:', e?.message || e);
    }
}

function showRestartHint() {
    const el = document.getElementById('languageRestartHint');
    if (el) el.classList.remove('hidden');
}

function hideRestartHint() {
    const el = document.getElementById('languageRestartHint');
    if (el) el.classList.add('hidden');
}

function openRestartModal() {
    const overlay = document.getElementById('restartModalOverlay');
    if (!overlay) return;
    overlay.classList.remove('hidden');
    overlay.classList.add('active');
}

function closeRestartModal() {
    const overlay = document.getElementById('restartModalOverlay');
    if (!overlay) return;
    overlay.classList.add('hidden');
    overlay.classList.remove('active');
}

function hasPendingLanguageChange() {
    const activeLanguage = String(
        window.i18n?.getLanguage?.()
        || state.settings?.ui?.language
        || state.settings?.lang
        || ''
    ).trim();
    const selectedLanguage = String(
        elements.languageSelect?.value
        || state.settings?.ui?.language
        || state.settings?.lang
        || ''
    ).trim();
    return !!(selectedLanguage && activeLanguage && selectedLanguage !== activeLanguage);
}

async function confirmAndRelaunchApp() {
    try {
        await saveSettings();
    } catch (error) {
        console.error('[APP] save before relaunch failed:', error);
    }

    try {
        const ok = await window.aurivo?.app?.relaunch?.();
        if (!ok) {
            closeRestartModal();
            safeNotify(uiT('restart.failed', 'Uygulama yeniden başlatılamadı.'), 'error', 2200);
        }
    } catch (error) {
        console.error('[APP] relaunch request failed:', error);
        closeRestartModal();
        safeNotify(uiT('restart.failed', 'Uygulama yeniden başlatılamadı.'), 'error', 2200);
    }
}

// C++ Ses Motoru mevcut mu kontrol et ve başlat
async function checkNativeAudio() {
    try {
        if (window.aurivo && window.aurivo.audio) {
            const isAvailable = window.aurivo.audio.isNativeAvailable();
            console.log('Native Audio mevcut:', isAvailable);

            if (isAvailable) {
                // Ses Motoru'nu başlat
                const initResult = await window.aurivo.audio.init();
                console.log('Audio Engine init sonucu:', initResult);

                if (initResult && initResult.success) {
                    useNativeAudio = true;
                    console.log('✓ C++ Audio Engine başarıyla başlatıldı');

                    // AGC'yi kapat - ses bozukluğunu önlemek için
                    if (window.aurivo.audio.autoGain) {
                        window.aurivo.audio.autoGain.setEnabled(false);
                        console.log('AGC devre dışı bırakıldı');
                        try {
                            const currentVol = Math.max(0, Math.min(100, Number(state.volume) || 40));
                            window.aurivo.audio.setVolume(currentVol / 100);
                        } catch {
                            // yoksay
                        }
                    }

                    // ✨ EQ + Ses Efekti ayarlarını yükle ve uygula
                    await loadAndApplyEQSettings();
                    await loadAndApplyStartupSfxSettings();
                } else {
                    useNativeAudio = false;
                    console.warn('C++ Audio Engine başlatılamadı:', initResult?.error);
                }
            } else {
                useNativeAudio = false;
            }
        }
    } catch (e) {
        console.error('Native audio kontrol hatası:', e);
        useNativeAudio = false;
    }
}

// EQ ayarlarını yükle ve Ses Motoru'na uygula
async function loadAndApplyEQSettings() {
    try {
        if (!window.aurivo?.loadSettings || !window.aurivo?.ipcAudio?.eq) {
            console.warn('[MAIN WINDOW] EQ yükleme atlandı (API yok)');
            return;
        }

        console.log('[MAIN WINDOW] Kayıtlı EQ ayarları yükleniyor...');
        const settings = await window.aurivo.loadSettings();
        const eq32 = settings?.sfxScopes?.music?.eq32 || settings?.sfx?.eq32;

        if (!eq32 || !Array.isArray(eq32.bands)) {
            console.log('[MAIN WINDOW] Kayıtlı EQ yok, varsayılan kullanılıyor');
            return;
        }

        console.log('[MAIN WINDOW] EQ ayarları bulundu:', {
            preset: eq32.lastPreset?.name || 'Düz',
            bantSayısı: eq32.bands.length
        });

        // EQ bantlarını Ses Motoru'na uygula
        eq32.bands.forEach((gain, index) => {
            window.aurivo.ipcAudio.eq.setBand(index, gain);
        });

        // Aurivo Modülü (Bass, Mid, Treble, Stereo)
        if (window.aurivo.ipcAudio.module) {
            if (typeof eq32.bass === 'number') {
                window.aurivo.ipcAudio.module.setBass(eq32.bass);
            }
            if (typeof eq32.mid === 'number') {
                window.aurivo.ipcAudio.module.setMid(eq32.mid);
            }
            if (typeof eq32.treble === 'number') {
                window.aurivo.ipcAudio.module.setTreble(eq32.treble);
            }
            if (typeof eq32.stereoExpander === 'number') {
                window.aurivo.ipcAudio.module.setStereoExpander(eq32.stereoExpander);
            }
        }

        // Denge
        if (window.aurivo.ipcAudio.balance && typeof eq32.balance === 'number') {
            window.aurivo.ipcAudio.balance.set(eq32.balance);
        }

        console.log('[MAIN WINDOW] ✓ EQ ayarları uygulandı:', eq32.lastPreset?.name || 'Düz');
    } catch (err) {
        console.error('[MAIN WINDOW] EQ yükleme hatası:', err);
    }
}

function getMusicSfxEffect(settings, effectName) {
    const key = String(effectName || '').trim().toLowerCase();
    return settings?.sfxScopes?.music?.[key] || settings?.sfx?.[key] || {};
}

async function loadAndApplyStartupSfxSettings() {
    try {
        if (!window.aurivo?.loadSettings || !window.aurivo?.ipcAudio) return;

        const settings = await window.aurivo.loadSettings();
        const ipcAudio = window.aurivo.ipcAudio;
        const audioApi = window.aurivo.audio;
        const master = getMusicSfxEffect(settings, 'master');
        const audiophile = getMusicSfxEffect(settings, 'audiophile');
        const compressor = getMusicSfxEffect(settings, 'compressor');
        const limiter = getMusicSfxEffect(settings, 'limiter');
        const bassboost = getMusicSfxEffect(settings, 'bassboost');
        const noisegate = getMusicSfxEffect(settings, 'noisegate');
        const deesser = getMusicSfxEffect(settings, 'deesser');
        const exciter = getMusicSfxEffect(settings, 'exciter');
        const stereowidener = getMusicSfxEffect(settings, 'stereowidener');
        const echo = getMusicSfxEffect(settings, 'echo');
        const softecho = getMusicSfxEffect(settings, 'softecho');
        const autogain = getMusicSfxEffect(settings, 'autogain');
        const truepeak = getMusicSfxEffect(settings, 'truepeak');
        const crossfeed = getMusicSfxEffect(settings, 'crossfeed');
        const surround = getMusicSfxEffect(settings, 'surround');
        const bassmono = getMusicSfxEffect(settings, 'bassmono');

        if (audioApi?.setDSPEnabled) {
            await audioApi.setDSPEnabled(master?.enabled !== false);
        }

        if (ipcAudio?.preamp?.set) {
            await ipcAudio.preamp.set(Number(audiophile?.preamp) || 0);
        }
        if (ipcAudio?.outputProfile?.configure) {
            await ipcAudio.outputProfile.configure({
                exclusiveMode: audiophile?.exclusiveMode === true,
                outputDevice: String(audiophile?.outputDevice || 'default'),
                sampleRate: String(audiophile?.sampleRate || 'auto')
            });
        }

        if (ipcAudio?.compressor) {
            await ipcAudio.compressor.enable(compressor?.enabled === true);
            await ipcAudio.compressor.setThreshold(Number(compressor?.threshold) || -20);
            await ipcAudio.compressor.setRatio(Number(compressor?.ratio) || 4);
            await ipcAudio.compressor.setAttack(Number(compressor?.attack) || 10);
            await ipcAudio.compressor.setRelease(Number(compressor?.release) || 100);
            await ipcAudio.compressor.setMakeupGain(Number(compressor?.makeupGain) || 0);
            await ipcAudio.compressor.setKnee(Number(compressor?.knee) || 3);
        }

        if (ipcAudio?.limiter) {
            await ipcAudio.limiter.enable(limiter?.enabled === true);
            await ipcAudio.limiter.setCeiling(Number(limiter?.ceiling) || -0.3);
            await ipcAudio.limiter.setRelease(Number(limiter?.release) || 50);
            await ipcAudio.limiter.setLookahead(Number(limiter?.lookahead) || 5);
            await ipcAudio.limiter.setGain(Number(limiter?.gain) || 0);
        }

        if (ipcAudio?.bassBoostDsp?.set) {
            await ipcAudio.bassBoostDsp.set(
                bassboost?.enabled === true,
                Number(bassboost?.gain) || 6,
                Number(bassboost?.frequency) || 80
            );
        } else if (ipcAudio?.bassEnhancer) {
            await ipcAudio.bassEnhancer.enable(bassboost?.enabled === true);
            await ipcAudio.bassEnhancer.setFrequency(Number(bassboost?.frequency) || 80);
            await ipcAudio.bassEnhancer.setGain(Number(bassboost?.gain) || 6);
            await ipcAudio.bassEnhancer.setHarmonics(Number(bassboost?.harmonics) || 50);
            await ipcAudio.bassEnhancer.setWidth(Number(bassboost?.width) || 1.5);
            await ipcAudio.bassEnhancer.setMix(Number(bassboost?.mix) || 50);
        }

        if (ipcAudio?.noiseGate) {
            await ipcAudio.noiseGate.enable(noisegate?.enabled === true);
            await ipcAudio.noiseGate.setThreshold(Number(noisegate?.threshold) || -40);
            await ipcAudio.noiseGate.setAttack(Number(noisegate?.attack) || 5);
            await ipcAudio.noiseGate.setHold(Number(noisegate?.hold) || 100);
            await ipcAudio.noiseGate.setRelease(Number(noisegate?.release) || 150);
            await ipcAudio.noiseGate.setRange(Number(noisegate?.range) || -80);
        }

        if (ipcAudio?.deEsser) {
            await ipcAudio.deEsser.enable(deesser?.enabled === true);
            await ipcAudio.deEsser.setFrequency(Number(deesser?.frequency) || 7000);
            await ipcAudio.deEsser.setThreshold(Number(deesser?.threshold) || -30);
            await ipcAudio.deEsser.setRatio(Number(deesser?.ratio) || 4);
            await ipcAudio.deEsser.setRange(Number(deesser?.range) || -12);
            await ipcAudio.deEsser.setListenMode(deesser?.listenMode === true);
        }

        if (ipcAudio?.exciter) {
            await ipcAudio.exciter.enable(exciter?.enabled === true);
            await ipcAudio.exciter.setAmount(Number(exciter?.amount) || 50);
            await ipcAudio.exciter.setFrequency(Number(exciter?.frequency) || 3000);
            await ipcAudio.exciter.setHarmonics(Number(exciter?.harmonics) || 50);
            await ipcAudio.exciter.setMix(Number(exciter?.mix) || 30);
        }

        if (ipcAudio?.stereoWidener) {
            await ipcAudio.stereoWidener.enable(stereowidener?.enabled === true);
            await ipcAudio.stereoWidener.setWidth(Number(stereowidener?.width) || 100);
            await ipcAudio.stereoWidener.setBalance(Number(stereowidener?.centerLevel) || 0);
            await ipcAudio.stereoWidener.setDelay(Number(stereowidener?.sideLevel) || 0);
            await ipcAudio.stereoWidener.setBassCutoff(Number(stereowidener?.bassToMono) || 200);
        }

        if (ipcAudio?.echo) {
            await ipcAudio.echo.enable(echo?.enabled === true);
            await ipcAudio.echo.setDelay(Number(echo?.delay) || 250);
            await ipcAudio.echo.setFeedback(Number(echo?.feedback) || 40);
            await ipcAudio.echo.setWetMix(Number(echo?.wetDry) || 30);
            await ipcAudio.echo.setHighCut(Number(echo?.highCut) || 8000);
        }

        if (ipcAudio?.softEcho) {
            await ipcAudio.softEcho.enable(softecho?.enabled === true);
            await ipcAudio.softEcho.setDelay(Number(softecho?.delay) || 520);
            await ipcAudio.softEcho.setFeedback(Number(softecho?.feedback) || 8);
            await ipcAudio.softEcho.setWetMix(Number(softecho?.wetMix) || 28);
            await ipcAudio.softEcho.setHighCut(Number(softecho?.highCut) || 4200);
            await ipcAudio.softEcho.setStereoMode(softecho?.stereo === true);
        }

        if (ipcAudio?.autoGain) {
            await ipcAudio.autoGain.setEnabled(autogain?.enabled === true);
            await ipcAudio.autoGain.setTarget(Number(autogain?.targetLevel) || -14);
            await ipcAudio.autoGain.setMaxGain(Number(autogain?.maxGain) || 12);
            await ipcAudio.autoGain.setMode(String(autogain?.speed || 'medium'));
        }

        if (ipcAudio?.truePeakLimiter) {
            await ipcAudio.truePeakLimiter.setEnabled(truepeak?.enabled === true);
            await ipcAudio.truePeakLimiter.setCeiling(Number(truepeak?.ceiling) || -0.1);
            await ipcAudio.truePeakLimiter.setRelease(Number(truepeak?.release) || 50);
            await ipcAudio.truePeakLimiter.setLookahead(Number(truepeak?.lookahead) || 5);
            await ipcAudio.truePeakLimiter.setInputGain(Number(truepeak?.drive) || 0);
            await ipcAudio.truePeakLimiter.setOversampling(Number(truepeak?.oversampling) || 4);
            await ipcAudio.truePeakLimiter.setLinkChannels(truepeak?.linkChannels !== false);
        }

        if (ipcAudio?.crossfeed) {
            await ipcAudio.crossfeed.enable(crossfeed?.enabled === true);
            await ipcAudio.crossfeed.setLevel(Number(crossfeed?.level) || 30);
            await ipcAudio.crossfeed.setDelay(Number(crossfeed?.delay) || 0.3);
            await ipcAudio.crossfeed.setLowCut(Number(crossfeed?.lowCut) || 700);
            await ipcAudio.crossfeed.setHighCut(Number(crossfeed?.highCut) || 4000);
        }

        if (ipcAudio?.surround) {
            await ipcAudio.surround.enable(surround?.enabled === true);
            await ipcAudio.surround.setCenter(Number(surround?.center) || 0);
            await ipcAudio.surround.setSurround(Number(surround?.surround) || 0);
            await ipcAudio.surround.setLfe(Number(surround?.lfe) || 0);
            await ipcAudio.surround.setCrossover(Number(surround?.crossover) || 110);
            await ipcAudio.surround.setDelay(Number(surround?.delay) || 8);
            await ipcAudio.surround.setMix(Number(surround?.mix) || 75);
        }

        if (ipcAudio?.bassMono) {
            await ipcAudio.bassMono.enable(bassmono?.enabled === true);
            await ipcAudio.bassMono.setCutoff(Number(bassmono?.cutoff) || 120);
            await ipcAudio.bassMono.setSlope(Number(bassmono?.slope) || 24);
            await ipcAudio.bassMono.setStereoWidth(Number(bassmono?.stereoWidth) || 100);
        }

        console.log('[MAIN WINDOW] ✓ Kayıtlı ses efektleri startup sırasında uygulandı');
    } catch (err) {
        console.warn('[MAIN WINDOW] Ses efektleri startup senkronu atlandı:', err?.message || err);
    }
}

