const WEB_ALLOWED_SUFFIXES = [
    '.youtube.com',
    '.google.com',
    '.googleusercontent.com',
    '.deezer.com',
    '.soundcloud.com',
    '.mixcloud.com',
    '.facebook.com',
    '.instagram.com',
    '.tiktok.com',
    '.x.com',
    '.twitter.com',
    '.reddit.com',
    '.twitch.tv',
    '.whatsapp.com',
    '.telegram.org'
];

const WEB_SYNC_ALLOWED_HOSTS = new Set([
    'youtube.com',
    'www.youtube.com',
    'm.youtube.com',
    'music.youtube.com',
    'youtu.be',
    'www.deezer.com',
    'deezer.com',
    'soundcloud.com',
    'www.soundcloud.com',
    'mixcloud.com',
    'www.mixcloud.com',
    'twitch.tv',
    'www.twitch.tv',
    'web.whatsapp.com',
    'web.telegram.org'
]);

function parseHttpUrl(raw) {
    try {
        const u = new URL(String(raw || '').trim());
        if (!/^https?:$/i.test(u.protocol)) return null;
        return u;
    } catch {
        return null;
    }
}

function isAllowedWebUrl(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return false;
    const host = String(parsed.hostname || '').toLowerCase();
    if (WEB_ALLOWED_HOSTS.has(host)) return true;
    return WEB_ALLOWED_SUFFIXES.some((suffix) => host.endsWith(suffix));
}

function detectPlatformFromUrl(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return '';
    const host = String(parsed.hostname || '').toLowerCase();
    if (host === 'music.youtube.com') return 'ytmusic';
    if (host === 'youtu.be' || host === 'youtube.com' || host === 'www.youtube.com' || host === 'm.youtube.com' || host.endsWith('.youtube.com')) return 'youtube';
    if (host === 'deezer.com' || host === 'www.deezer.com' || host.endsWith('.deezer.com')) return 'deezer';
    if (host === 'soundcloud.com' || host === 'www.soundcloud.com' || host.endsWith('.soundcloud.com')) return 'soundcloud';
    if (host === 'facebook.com' || host === 'www.facebook.com' || host === 'm.facebook.com' || host.endsWith('.facebook.com')) return 'facebook';
    if (host === 'instagram.com' || host === 'www.instagram.com' || host.endsWith('.instagram.com')) return 'instagram';
    if (host === 'tiktok.com' || host === 'www.tiktok.com' || host === 'm.tiktok.com' || host.endsWith('.tiktok.com')) return 'tiktok';
    if (host === 'x.com' || host === 'www.x.com' || host === 'twitter.com' || host === 'www.twitter.com' || host.endsWith('.x.com') || host.endsWith('.twitter.com')) return 'x';
    if (host === 'reddit.com' || host === 'www.reddit.com' || host === 'old.reddit.com' || host.endsWith('.reddit.com')) return 'reddit';
    if (host === 'twitch.tv' || host === 'www.twitch.tv' || host.endsWith('.twitch.tv')) return 'twitch';
    if (host === 'web.whatsapp.com' || host === 'whatsapp.com' || host === 'www.whatsapp.com' || host.endsWith('.whatsapp.com')) return 'whatsapp';
    if (host === 'web.telegram.org' || host === 'telegram.org' || host === 'www.telegram.org' || host === 't.me' || host === 'www.t.me' || host.endsWith('.telegram.org')) return 'telegram';
    if (host === 'mixcloud.com' || host === 'www.mixcloud.com' || host.endsWith('.mixcloud.com')) return 'mixcloud';
    return '';
}

function normalizeYouTubeNavigationUrl(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return '';
    const host = String(parsed.hostname || '').toLowerCase();
    const isYouTubeHost = host === 'youtu.be' || host === 'youtube.com' || host === 'www.youtube.com' || host === 'm.youtube.com' || host === 'music.youtube.com' || host.endsWith('.youtube.com');
    if (!isYouTubeHost) return '';
    parsed.hash = '';
    return parsed.toString();
}

function isYouTubeWatchLikeUrl(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return false;
    const host = String(parsed.hostname || '').toLowerCase();
    const path = String(parsed.pathname || '').toLowerCase();
    const search = String(parsed.search || '').toLowerCase();
    if (!(host === 'youtu.be' || host === 'youtube.com' || host === 'www.youtube.com' || host === 'm.youtube.com' || host === 'music.youtube.com' || host.endsWith('.youtube.com'))) {
        return false;
    }
    return (
        host === 'music.youtube.com' ||
        path.includes('/watch') ||
        path.includes('/shorts') ||
        path.includes('/live') ||
        (path.includes('/playlist') && search.includes('list='))
    );
}

function resetYouTubeNavigationHistory() {
    webPlatformRuntime.youtubeNavBackStack = [];
    webPlatformRuntime.youtubeNavForwardStack = [];
    webPlatformRuntime.youtubeNavCurrentUrl = '';
    webPlatformRuntime.youtubeNavApplying = false;
}

function recordYouTubeNavigation(url) {
    const normalized = normalizeYouTubeNavigationUrl(url);
    if (!normalized || !isYoutubeHost(normalized)) {
        if (!webPlatformRuntime.youtubeNavApplying) {
            resetYouTubeNavigationHistory();
        } else {
            webPlatformRuntime.youtubeNavApplying = false;
        }
        return;
    }

    if (webPlatformRuntime.youtubeNavApplying) {
        webPlatformRuntime.youtubeNavCurrentUrl = normalized;
        webPlatformRuntime.youtubeNavApplying = false;
        return;
    }

    const current = String(webPlatformRuntime.youtubeNavCurrentUrl || '').trim();
    if (!current) {
        webPlatformRuntime.youtubeNavCurrentUrl = normalized;
        return;
    }
    if (current === normalized) return;

    const backStack = Array.isArray(webPlatformRuntime.youtubeNavBackStack) ? webPlatformRuntime.youtubeNavBackStack : [];
    if (backStack[backStack.length - 1] !== current) {
        backStack.push(current);
    }
    while (backStack.length > 80) backStack.shift();

    webPlatformRuntime.youtubeNavBackStack = backStack;
    webPlatformRuntime.youtubeNavForwardStack = [];
    webPlatformRuntime.youtubeNavCurrentUrl = normalized;
}

function getYoutubeVideoIdFromUrl(raw) {
    try {
        const parsed = parseHttpUrl(raw);
        if (!parsed) return '';
        const host = String(parsed.hostname || '').toLowerCase();
        if (host === 'youtu.be') {
            return String(parsed.pathname || '').split('/').filter(Boolean)[0] || '';
        }
        const v = String(parsed.searchParams.get('v') || '').trim();
        if (v) return v;
        const shorts = String(parsed.pathname || '').match(/\/shorts\/([a-zA-Z0-9_-]{6,})/);
        if (shorts?.[1]) return shorts[1];
    } catch {
        // yoksay
    }
    return '';
}

function getWebCoverFallbackByUrl(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return '';
    const host = String(parsed.hostname || '').toLowerCase();
    const isYoutube =
        host === 'youtu.be' ||
        host === 'youtube.com' ||
        host === 'www.youtube.com' ||
        host === 'm.youtube.com' ||
        host.endsWith('.youtube.com');
    if (!isYoutube) return '';
    const videoId = getYoutubeVideoIdFromUrl(parsed.toString());
    if (!videoId) return '';
    return `https://i.ytimg.com/vi/${encodeURIComponent(videoId)}/hqdefault.jpg`;
}

function syncActivePlatformButtonByUrl(rawUrl) {
    if (!elements.platformBtns || !elements.platformBtns.length) return;
    const detected = detectPlatformFromUrl(rawUrl);
    if (!detected) return;
    const activeBefore = document.querySelector('.platform-btn.active');
    const activeBeforeKey = String(activeBefore?.dataset?.platform || '').toLowerCase();
    // Aynı platform içinde (örn. YouTube video <-> YouTube ana sayfa) gezinirken
    // platform kartı/kapak art tekrar güncellenmesin.
    if (activeBeforeKey && activeBeforeKey === detected) {
        const quickTitle = String(state.webTitle || state.webPendingTitle || '').trim();
        if (quickTitle && elements.nowPlayingLabel) {
            elements.nowPlayingLabel.textContent = `${uiT('nowPlaying.prefix', 'Now Playing')}: ${quickTitle}`;
        }
        return;
    }
    let matchedBtn = null;
    elements.platformBtns.forEach((btn) => {
        const key = String(btn.dataset.platform || '').toLowerCase();
        const isMatch = key === detected;
        btn.classList.toggle('active', isMatch);
        if (isMatch) matchedBtn = btn;
    });
    if (matchedBtn) {
        state.webCurrentPlatform = detected;
        if (!state.settings || typeof state.settings !== 'object') state.settings = {};
        if (!state.settings.ui || typeof state.settings.ui !== 'object') state.settings.ui = {};
        state.settings.ui.lastWebPlatform = detected;
        const platformName = matchedBtn.querySelector('span')?.textContent?.trim();
        if (platformName && elements.nowPlayingLabel) {
            const quickTitle = String(state.webTitle || state.webPendingTitle || '').trim();
            elements.nowPlayingLabel.textContent = `${uiT('nowPlaying.prefix', 'Now Playing')}: ${quickTitle || platformName}`;
        }
        updatePlatformCover(detected);
    }
}

function isYoutubeHost(raw) {
    const parsed = parseHttpUrl(raw);
    if (!parsed) return false;
    const host = String(parsed.hostname || '').toLowerCase();
    return host === 'youtube.com' ||
        host === 'www.youtube.com' ||
        host === 'm.youtube.com' ||
        host === 'music.youtube.com' ||
        host.endsWith('.youtube.com') ||
        host.endsWith('.googlevideo.com') ||
        host.endsWith('.ytimg.com');
}

function getEmbeddedDesktopUserAgent() {
    const nativeUa = String(navigator.userAgent || '');
    const stripped = nativeUa
        .replace(/\sElectron\/[^\s)]+/gi, '')
        .replace(/\sAurivo\/[^\s)]+/gi, '')
        .replace(/\s{2,}/g, ' ')
        .trim();
    // Daha güncel Chrome kimliği: bazı servisler eski UA'ları kısıtlayabiliyor.
    return stripped || 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/132.0.0.0 Safari/537.36';
}

function shouldInjectWebSync(url) {
    const parsed = parseHttpUrl(url);
    if (!parsed) return false;
    const host = String(parsed.hostname || '').toLowerCase();

    // Kimlik dogrulama sayfalarinda script enjeksiyonu yapma.
    // Bu sayfalardaki fingerprint/policy kontrolleri daha hassas oldugu icin
    // yalnizca medya senkronu gereken hostlarda enjeksiyon calissin.
    if (
        host === 'accounts.google.com' ||
        host === 'myaccount.google.com' ||
        host === 'oauth2.googleapis.com'
    ) {
        return false;
    }

    if (WEB_SYNC_ALLOWED_HOSTS.has(host)) return true;

    return host.endsWith('.youtube.com') ||
        host.endsWith('.deezer.com') ||
        host.endsWith('.soundcloud.com') ||
        host.endsWith('.mixcloud.com') ||
        host.endsWith('.twitch.tv') ||
        host.endsWith('.whatsapp.com') ||
        host.endsWith('.telegram.org');
}

async function getSecurityStateSafe() {
    try {
        const data = await window.aurivo?.webSecurity?.getSecurityState?.();
        return {
            vpnDetected: !!data?.vpnDetected,
            vpnInterfaces: Array.isArray(data?.vpnInterfaces) ? data.vpnInterfaces : []
        };
    } catch {
        return { vpnDetected: false, vpnInterfaces: [] };
    }
}

function isStrictVpnBlockEnabled() {
    return !!state.settings?.security?.strictVpnBlock;
}

function isWebAllowlistEnforced() {
    return !!state.settings?.security?.enforceAllowlist;
}

function updateAdblockModeUI() {
    const adblock = ensureAdblockSettings();
    window.AurivoAdblockSettings?.updateModeUI?.({
        elements,
        adblock,
        normalizeMode: normalizeAdblockMode
    });
}

function readAdblockSettingsFromUI() {
    const adblock = ensureAdblockSettings();
    adblock.mode = normalizeAdblockMode(adblock.mode);
    return window.AurivoAdblockSettings?.readSettingsFromUI?.({ elements, adblock }) || adblock;
}

function reloadWebViewForAdblock(reason = 'unknown', details = {}) {
    if (!elements.webView) return false;
    try {
        const url = getWebViewUrlSafe();
        console.log('[ADBLOCK] platform reload by settings change', {
            reason: String(reason || 'unknown'),
            url,
            ...details
        });
        elements.webView.reload();
        return true;
    } catch (e) {
        console.warn('[ADBLOCK] platform reload failed', {
            reason: String(reason || 'unknown'),
            error: e?.message || String(e || '')
        });
        return false;
    }
}

function setAdblockMode(mode) {
    const nextMode = normalizeAdblockMode(mode);
    const adblock = ensureAdblockSettings();
    const prevMode = normalizeAdblockMode(adblock.mode);
    adblock.mode = nextMode;
    adblockRuntime.pendingModeChange = nextMode !== prevMode;
    updateAdblockModeUI();
    applyAdblockRuntimeConfig();

    if (nextMode !== prevMode && adblock.autoRefreshOnModeChange && elements.webView) {
        const reloaded = reloadWebViewForAdblock('setAdblockMode', {
            prevMode,
            nextMode
        });
        if (reloaded) adblockRuntime.pendingModeChange = false;
    }
}

function updateAdblockBadge(blockedCount) {
    window.AurivoAdblockSettings?.updateBadge?.({
        elements,
        blockedCount,
        showCount: !!ensureAdblockSettings().showBlockedCount
    });
}

function getActiveAdblockCounterKey() {
    const inWeb = state.currentPage === 'web' || state.currentPanel === 'web' || state.activeMedia === 'web';
    if (!inWeb) return '';
    const activeBtn = document.querySelector('.platform-btn.active');
    const key = String(activeBtn?.dataset?.platform || '').trim().toLowerCase();
    return key || 'web';
}

function resetAdblockVisibleCounter() {
    const key = getActiveAdblockCounterKey();
    if (key) {
        adblockRuntime.currentCounterKey = key;
        adblockRuntime.counterBaseByKey.set(key, Number(adblockRuntime.lastAbsoluteBlocked || 0));
    }
    adblockRuntime.lastBlocked = 0;
    updateAdblockBadge(0);
}

async function refreshAdblockStats(showToast = false) {
    const inWeb = state.currentPage === 'web' || state.currentPanel === 'web' || state.activeMedia === 'web';
    const key = getActiveAdblockCounterKey();
    return window.AurivoAdblockSettings?.refreshStats?.({
        getStats: () => window.aurivo?.adblock?.getStats?.(),
        elements,
        updateBadge: updateAdblockBadge,
        setBlockedCount: (value) => {
            const absoluteBlocked = Number(value) || 0;
            adblockRuntime.lastAbsoluteBlocked = absoluteBlocked;

            if (!inWeb || !key) {
                adblockRuntime.lastBlocked = 0;
                updateAdblockBadge(0);
                return;
            }

            if (!adblockRuntime.counterBaseByKey.has(key)) {
                adblockRuntime.counterBaseByKey.set(key, absoluteBlocked);
            }

            const base = Number(adblockRuntime.counterBaseByKey.get(key) || 0);
            const visible = Math.max(0, absoluteBlocked - base);
            adblockRuntime.currentCounterKey = key;
            adblockRuntime.lastBlocked = visible;
            updateAdblockBadge(visible);
        },
        notify: safeNotify,
        showToast
    });
}

async function openAdblockDashboardPanel() {
    try {
        const ok = await window.aurivo?.adblock?.openDashboard?.();
        if (ok) return true;
    } catch (e) {
        console.warn('[ADBLOCK] openDashboard error:', e?.message || e);
    }
    safeNotify('Aurivo paneli açılamadı', 'error', 2000);
    return false;
}

function startAdblockStatsPolling() {
    if (adblockRuntime.pollTimer) {
        clearInterval(adblockRuntime.pollTimer);
        adblockRuntime.pollTimer = null;
    }
    refreshAdblockStats(false);
    adblockRuntime.pollTimer = setInterval(() => {
        const inWeb = state.currentPage === 'web' || state.currentPanel === 'web' || state.activeMedia === 'web';
        const settingsOpen = isPageVisible(elements.settingsPage);
        if (inWeb || settingsOpen) {
            refreshAdblockStats(false);
        }
    }, 1200);
}

function triggerAdblockNavBurstRefresh() {
    refreshAdblockStats(false);
    let remaining = 4;
    if (adblockRuntime.navBurstTimer) {
        clearInterval(adblockRuntime.navBurstTimer);
        adblockRuntime.navBurstTimer = null;
    }
    adblockRuntime.navBurstTimer = setInterval(() => {
        refreshAdblockStats(false);
        remaining -= 1;
        if (remaining <= 0) {
            clearInterval(adblockRuntime.navBurstTimer);
            adblockRuntime.navBurstTimer = null;
        }
    }, 450);
}

function stopAdblockStatsPolling() {
    if (!adblockRuntime.pollTimer) return;
    clearInterval(adblockRuntime.pollTimer);
    adblockRuntime.pollTimer = null;
    if (adblockRuntime.navBurstTimer) {
        clearInterval(adblockRuntime.navBurstTimer);
        adblockRuntime.navBurstTimer = null;
    }
}

function stopSettingsBackgroundWork() {
    stopAudioOutputMonitor();
    stopAudioOutputLevelMeter();
    stopAdblockStatsPolling();
}

function resumeSettingsBackgroundWork() {
    if (!isStandaloneSettingsMode()) return;
    if (document.hidden || !document.hasFocus()) {
        stopSettingsBackgroundWork();
        return;
    }

    const activeTab = getActiveSettingsTabName();
    if (activeTab === 'audio') {
        refreshSystemAudioState();
        startAudioOutputMonitor();
        startAudioOutputLevelMeter();
    } else if (activeTab === 'adblock') {
        startAdblockStatsPolling();
        refreshAdblockStats(false);
    } else if (activeTab === 'library') {
        refreshLibraryStats().catch(() => {});
    }
}

function updateSecurityUI() {
    updateSecurityUIAsync();
}

function isSecuritySettingsVisible() {
    return !!window.AurivoSecuritySettings?.isVisible?.({
        settingsPage: elements.settingsPage
    });
}

async function updateSecurityUIAsync() {
    return window.AurivoSecuritySettings?.updateUI?.({
        elements,
        getUrl: getWebViewUrlSafe,
        parseHttpUrl,
        getSecurityState: getSecurityStateSafe,
        translate: uiT,
        strictVpnBlock: !!state.settings?.security?.strictVpnBlock,
        enforceAllowlist: !!state.settings?.security?.enforceAllowlist
    });
}

function getWebSessionProfile() {
    return normalizeWebSessionProfile(state.settings?.security?.sessionProfile, 'persistent');
}

async function ensureWebIsolatedSessionInitialized(reason = 'web-entry') {
    if (getWebSessionProfile() !== 'isolated') {
        webIsolatedSessionPrepared = false;
        return true;
    }
    if (webIsolatedSessionPrepared) return true;
    try {
        const ok = await window.aurivo?.webSecurity?.clearData?.({ all: true });
        if (!ok) return false;
        webIsolatedSessionPrepared = true;
        safeNotify(
            uiT('securityPage.notify.sessionIsolatedReady', 'İzole web profili hazır: temiz bir oturum başlatıldı.'),
            'info',
            1800
        );
        console.log('[SECURITY] isolated web session prepared:', reason);
        return true;
    } catch {
        return false;
    }
}

function openDawlodWithCurrentWebUrl({ strictUrl = true } = {}) {
    if (!window.aurivo?.dawlod?.openWindow) {
        safeNotify('İndirme modülü bulunamadı (Aurivo-Dawlod).', 'error');
        return false;
    }

    const candidate = getWebViewUrlSafe();
    const url = (candidate && candidate !== 'about:blank' && /^https?:\/\//i.test(candidate)) ? candidate : '';
    if (strictUrl && !url) {
        safeNotify(uiT('securityPage.notify.invalidExternalUrl', 'Önce geçerli bir web sayfası açın (http/https).'), 'info');
        return false;
    }

    try {
        if (url) {
            window.aurivo.dawlod.openWindow({ url });
            try { window.aurivo?.clipboard?.setText?.(url); } catch {}
        } else {
            window.aurivo.dawlod.openWindow();
        }
        setUtilityRunningState('download', true);
        return true;
    } catch (e) {
        setUtilityRunningState('download', false);
        safeNotify(`İndirme penceresi açılamadı: ${e?.message || e}`, 'error');
        return false;
    }
}

function setupSecurityUI() {
    if (!elements.securityConnStatus) return;

    if (elements.securityAllowPopups && elements.webView) {
        elements.securityAllowPopups.addEventListener('change', () => {
            if (!elements.webView) return;
            if (elements.securityAllowPopups.checked) {
                elements.webView.setAttribute('allowpopups', '');
            } else {
                elements.webView.removeAttribute('allowpopups');
            }
        });
    }

    if (elements.securityStrictVpnBlock) {
        elements.securityStrictVpnBlock.addEventListener('change', async () => {
            if (!state.settings) state.settings = {};
            if (!state.settings.security || typeof state.settings.security !== 'object') {
                state.settings.security = {};
            }
            state.settings.security.strictVpnBlock = !!elements.securityStrictVpnBlock.checked;
            await saveSettings();
            updateSecurityUI();
        });
    }

    if (elements.securityEnforceAllowlist) {
        elements.securityEnforceAllowlist.addEventListener('change', async () => {
            if (!state.settings) state.settings = {};
            if (!state.settings.security || typeof state.settings.security !== 'object') {
                state.settings.security = {};
            }
            state.settings.security.enforceAllowlist = !!elements.securityEnforceAllowlist.checked;
            await saveSettings();
            updateSecurityUI();
        });
    }

    if (elements.securitySessionProfile) {
        elements.securitySessionProfile.addEventListener('change', async () => {
            if (!state.settings) state.settings = {};
            if (!state.settings.security || typeof state.settings.security !== 'object') {
                state.settings.security = {};
            }
            const profile = normalizeWebSessionProfile(elements.securitySessionProfile.value, 'persistent');
            elements.securitySessionProfile.value = profile;
            state.settings.security.sessionProfile = profile;
            if (profile !== 'isolated') {
                webIsolatedSessionPrepared = false;
            }
            await saveSettings();
            applySecuritySettingsToRuntime();
            updateSecurityUI();
        });
    }

    if (elements.securityCopyUrlBtn) {
        elements.securityCopyUrlBtn.addEventListener('click', async () => {
            const url = getWebViewUrlSafe();
            try {
                window.aurivo?.clipboard?.setText?.(url);
                safeNotify(uiT('securityPage.notify.urlCopied', 'URL copied.'), 'success');
            } catch (e) {
                safeNotify(uiT('securityPage.notify.urlCopyFailed', "Couldn't copy URL: {error}", { error: e?.message || e }), 'error');
            }
        });
    }

    if (elements.securityOpenInBrowserBtn) {
        elements.securityOpenInBrowserBtn.addEventListener('click', async () => {
            const url = getWebViewUrlSafe();
            if (!parseHttpUrl(url)) {
                safeNotify(uiT('securityPage.notify.invalidExternalUrl', 'Önce geçerli bir web sayfası açın (http/https).'), 'info');
                return;
            }
            try {
                const ok = await window.aurivo?.webSecurity?.openExternal?.(url);
                if (!ok) safeNotify(uiT('securityPage.notify.openInBrowserFailed', "Couldn't open in browser."), 'error');
            } catch (e) {
                safeNotify(uiT('securityPage.notify.openInBrowserError', "Couldn't open in browser: {error}", { error: e?.message || e }), 'error');
            }
        });
    }

    if (elements.securityQuickDownloadBtn) {
        elements.securityQuickDownloadBtn.addEventListener('click', () => {
            openDawlodWithCurrentWebUrl({ strictUrl: true });
        });
    }

    const clear = async (opts, okMsg) => {
        try {
            const ok = await window.aurivo?.webSecurity?.clearData?.(opts);
            if (!ok) {
                safeNotify(uiT('securityPage.notify.clearFailed', 'Clearing failed.'), 'error');
                return;
            }
            safeNotify(okMsg, 'success');
            updateSecurityUI();
        } catch (e) {
            safeNotify(uiT('securityPage.notify.clearError', 'Clearing error: {error}', { error: e?.message || e }), 'error');
        }
    };

    if (elements.securityClearCookiesBtn) {
        elements.securityClearCookiesBtn.addEventListener('click', () =>
            clear({ cookies: true }, uiT('securityPage.notify.cookiesCleared', 'Cookies cleared.'))
        );
    }
    if (elements.securityClearCacheBtn) {
        elements.securityClearCacheBtn.addEventListener('click', () =>
            clear({ cache: true }, uiT('securityPage.notify.cacheCleared', 'Cache cleared.'))
        );
    }
    if (elements.securityClearAllBtn) {
        elements.securityClearAllBtn.addEventListener('click', () =>
            clear({ all: true }, uiT('securityPage.notify.allCleared', 'Web data cleared.'))
        );
    }
    if (elements.securityResetWebBtn) {
        elements.securityResetWebBtn.addEventListener('click', () => {
            try {
                safeNavigateWebView('about:blank');
                safeNotify(uiT('securityPage.notify.webResetOk', 'Web has been reset.'), 'success');
                updateSecurityUI();
            } catch (e) {
                safeNotify(uiT('securityPage.notify.webResetFailed', "Couldn't reset Web: {error}", { error: e?.message || e }), 'error');
            }
        });
    }

    if (elements.securityExportCookiesBtn) {
        elements.securityExportCookiesBtn.addEventListener('click', async () => {
            try {
                const saveResult = await window.aurivo?.saveFile?.({
                    title: uiT('securityPage.buttons.exportCookies', 'Çerezleri dışa aktar'),
                    defaultPath: `aurivo-web-cookies-${Date.now()}.json`,
                    filters: [{ name: 'JSON', extensions: ['json'] }]
                });
                if (!saveResult?.path) return;

                const result = await window.aurivo?.webSecurity?.exportCookies?.(saveResult.path);
                if (!result?.ok) {
                    safeNotify(
                        uiT('securityPage.notify.cookiesExportFailed', 'Çerez dışa aktarımı başarısız: {error}', { error: result?.error || 'unknown' }),
                        'error'
                    );
                    return;
                }
                safeNotify(
                    uiT('securityPage.notify.cookiesExported', '{count} çerez dışa aktarıldı.', { count: Number(result?.count || 0) }),
                    'success'
                );
            } catch (e) {
                safeNotify(
                    uiT('securityPage.notify.cookiesExportFailed', 'Çerez dışa aktarımı başarısız: {error}', { error: e?.message || e }),
                    'error'
                );
            }
        });
    }

    if (elements.securityImportCookiesBtn) {
        elements.securityImportCookiesBtn.addEventListener('click', async () => {
            try {
                const files = await window.aurivo?.dialog?.openFiles?.({
                    title: uiT('securityPage.buttons.importCookies', 'Çerezleri içe aktar'),
                    filters: [
                        { name: 'JSON', extensions: ['json'] },
                        { name: uiT('common.allFiles', 'Tüm Dosyalar'), extensions: ['*'] }
                    ]
                });
                const first = Array.isArray(files) ? files[0] : null;
                if (!first?.path) return;

                const result = await window.aurivo?.webSecurity?.importCookies?.(first.path);
                if (!result?.ok) {
                    safeNotify(
                        uiT('securityPage.notify.cookiesImportFailed', 'Çerez içe aktarımı başarısız: {error}', { error: result?.error || 'unknown' }),
                        'error'
                    );
                    return;
                }
                safeNotify(
                    uiT(
                        'securityPage.notify.cookiesImported',
                        '{imported} çerez içe aktarıldı ({skipped} atlandı).',
                        {
                            imported: Number(result?.imported || 0),
                            skipped: Number(result?.skipped || 0)
                        }
                    ),
                    'success'
                );
                updateSecurityUI();
            } catch (e) {
                safeNotify(
                    uiT('securityPage.notify.cookiesImportFailed', 'Çerez içe aktarımı başarısız: {error}', { error: e?.message || e }),
                    'error'
                );
            }
        });
    }
}

// ============================================
// SİSTEM TEPSİSİ MEDYA KONTROLÜ
// ============================================
function executeMediaControlAction(action) {
    switch (action) {
        case 'play':
            if (!state.isPlaying) togglePlayPause();
            break;
        case 'pause':
            if (state.isPlaying) togglePlayPause();
            break;
        case 'play-pause':
            togglePlayPause();
            break;
        case 'stop':
            if (state.activeMedia === 'video') {
                stopVideo();
            } else if (state.activeMedia === 'web') {
                stopWeb();
            } else {
                stopAudioWithPlaybackFade();
            }
            state.isPlaying = false;
            updatePlayPauseIcon(false);
            break;
        case 'previous':
            if (state.activeMedia === 'video') {
                if (state.videoFiles.length > 1 && state.currentVideoIndex > 0) {
                    playPreviousVideo();
                }
            } else if (state.activeMedia === 'audio' || state.activeMedia === 'web') {
                playPreviousWithCrossfade();
            }
            break;
        case 'next':
            if (state.activeMedia === 'video') {
                if (state.videoFiles.length > 1 && state.currentVideoIndex >= 0 && state.currentVideoIndex < state.videoFiles.length - 1) {
                    playNextVideo();
                }
            } else if (state.activeMedia === 'audio' || state.activeMedia === 'web') {
                playNextWithCrossfade();
            }
            break;
        case 'mute-toggle':
            toggleMute();
            break;
        case 'stop-after-current':
            state.stopAfterCurrent = !state.stopAfterCurrent;
            console.log('Stop after current:', state.stopAfterCurrent);
            break;
        case 'like':
            // TODO: Beğen özelliği (favorilere ekle/çıkar)
            console.log('Like feature not implemented yet');
            break;
    }
}

function setupSystemTrayControl() {
    if (!window.aurivo || !window.aurivo.onMediaControl) {
        console.warn('System tray API yok');
        return;
    }

    // Ana süreçten gelen medya kontrol komutlarını dinle
    window.aurivo.onMediaControl((action) => {
        console.log('System tray media control:', action);
        executeMediaControlAction(action);

        // Her medya kontrolden sonra tepsi durumunu güncelle
        updateTrayState();
    });

    // MPRIS seek olayı (ortam oynatıcıdan süre çubuğu sürükleme)
    if (window.aurivo.onMPRISSeek) {
        window.aurivo.onMPRISSeek(async (offsetMicroseconds) => {
            console.log('MPRIS seek offset (relative):', offsetMicroseconds);
            const offsetSeconds = offsetMicroseconds / 1000000;

            // ÖNCE aktif medya tipine göre yönlendir (web oynuyorsa native motor'a düşmesin)
            if (state.activeMedia === 'web' && elements.webView) {
                // Web/YouTube Göreli Atlama
                try {
                    const delta = Number(offsetSeconds);
                    if (!isNaN(delta) && isFinite(delta)) {
                        await elements.webView.executeJavaScript(`
                            (function(){
                                var v = document.querySelector('video, audio');
                                if (v) v.currentTime = Math.max(0, (v.currentTime || 0) + (${delta}));
                            })();
                        `);
                    }
                } catch (e) {
                    console.warn('Web seek error:', e);
                }
                return;
            }

            // Mevcut pozisyonu al ve offset ekle (yalnızca ses sekmesinde)
            if (state.activeMedia === 'audio' && useNativeAudio && window.aurivo?.audio) {
                try {
                    const currentPos = await window.aurivo.audio.getPosition(); // ms
                    const newPos = currentPos + (offsetSeconds * 1000); // ms
                    await window.aurivo.audio.seek(Math.max(0, newPos));
                    console.log('Seeked to:', newPos / 1000, 'seconds');
                } catch (e) {
                    console.error('Seek error:', e);
                }
            } else {
                seekBy(offsetSeconds);
            }
        });
    }

    // MPRIS position olayı (ortam oynatıcıdan pozisyon değişikliği - MUTLAK pozisyon)
    if (window.aurivo.onMPRISPosition) {
        window.aurivo.onMPRISPosition(async (positionMicroseconds) => {
            const positionSeconds = positionMicroseconds / 1000000;
            console.log('MPRIS SetPosition (absolute):', positionSeconds, 'seconds');

            // ÖNCE aktif medya tipine göre yönlendir (web oynuyorsa native motor'a düşmesin)
            if (state.activeMedia === 'web' && elements.webView) {
                // Web/YouTube Mutlak Atlama
                try {
                    const pos = Number(positionSeconds);
                    if (!isNaN(pos) && isFinite(pos)) {
                        await elements.webView.executeJavaScript(`
                            (function(){
                                var v = document.querySelector('video, audio');
                                if (v) v.currentTime = Math.max(0, ${pos});
                            })();
                        `);
                        // Arayüzü anında güncelle (gecikmeyi önlemek için)
                        state.webPosition = pos;
                        updateMPRISMetadata();
                    }
                } catch (e) {
                    console.warn('Web position error:', e);
                }
                return;
            }

            if (state.activeMedia === 'audio' && useNativeAudio && window.aurivo?.audio) {
                try {
                    await window.aurivo.audio.seek(positionSeconds * 1000); // saniye -> milisaniye
                    console.log('Position set to:', positionSeconds, 'seconds');
                } catch (e) {
                    console.error('SetPosition error:', e);
                }
            } else if (state.activeMedia === 'video' && elements.videoPlayer) {
                try {
                    const video = elements.videoPlayer;
                    const d = Number(video.duration || 0);
                    const pos = Math.max(0, Number(positionSeconds) || 0);
                    const next = d > 0 ? Math.min(d, pos) : pos;
                    video.currentTime = next;
                    updateTimeDisplay();
                    updateMPRISMetadata();
                } catch (e) {
                    console.warn('Video position error:', e);
                }
            } else {
                const activePlayer = getActiveAudioPlayer();
                if (activePlayer) activePlayer.currentTime = positionSeconds;
            }
        });
    }

    console.log('System tray media control listener kuruldu');
}

// Sistem tepsisine güncel oynatma durumu gönder
function updateTrayState() {
    if (!window.aurivo || !window.aurivo.updateTrayState) return;

    let trackName = uiT('nowPlaying.none', 'No Track');
    if (state.activeMedia === 'video') {
        trackName = state.currentVideoPath
            ? (window.aurivo?.path?.basename?.(state.currentVideoPath) || String(state.currentVideoPath).split('/').pop() || 'Video')
            : 'Video';
    } else if (state.activeMedia === 'web') {
        trackName = state.webTitle || state.webPendingTitle || elements.nowPlayingLabel?.textContent?.replace(`${uiT('nowPlaying.prefix', 'Now Playing')}: `, '') || 'Web';
    } else {
        const currentTrack = state.playlist[state.currentIndex];
        trackName = currentTrack ? (currentTrack.title || currentTrack.name || uiT('nowPlaying.unknownTrack', 'Unknown Track')) : uiT('nowPlaying.none', 'No Track');
    }

    window.aurivo.updateTrayState({
        isPlaying: state.isPlaying,
        isMuted: state.isMuted,
        stopAfterCurrent: state.stopAfterCurrent,
        currentTrack: trackName
    });
}

// Web/YouTube gezintisinde MPRIS'i sıfırla
async function handleWebNavigation(event) {
    triggerAdblockNavBurstRefresh();
    const eventUrl = String(event?.url || '').trim();
    const currentUrl = eventUrl || getWebViewUrlSafe();
    if (state.activeMedia === 'web') {
        const sec = await getSecurityStateSafe();
        if (sec.vpnDetected) {
            if (isStrictVpnBlockEnabled() && !isYoutubeHost(currentUrl)) {
                safeNavigateWebView('about:blank');
                safeNotify(uiT('securityPage.notify.vpnBlocked', 'VPN algılandı. Güvenlik nedeniyle Web sekmesi geçici olarak engellendi.'), 'error');
                if (isSecuritySettingsVisible()) updateSecurityUI();
                return;
            }
            if (!securityRuntime.vpnWarned) {
                securityRuntime.vpnWarned = true;
                safeNotify(uiT('securityPage.notify.vpnWarning', 'VPN algılandı. Güvenlik için yalnızca izinli platformlar açılacaktır.'), 'info');
            }
        } else {
            securityRuntime.vpnWarned = false;
        }
        // Geçiş anında URL kısa süreli boş olabilir; bu durumda sayfayı zorla sıfırlama.
        // Yalnızca gerçek http/https URL'leri allowlist ile doğrula.
        if (isWebAllowlistEnforced() && currentUrl && currentUrl !== 'about:blank') {
            const parsedCurrent = parseHttpUrl(currentUrl);
            if (parsedCurrent && !isAllowedWebUrl(parsedCurrent.toString())) {
                safeNavigateWebView('about:blank');
                safeNotify(uiT('securityPage.notify.urlBlocked', 'Bu adres güvenlik politikası nedeniyle engellendi.'), 'error');
                if (isSecuritySettingsVisible()) updateSecurityUI();
                return;
            }
        }
    }

    if (state.activeMedia === 'web') {
        resetWebDaliAttachMetrics('web-navigation');
        syncActivePlatformButtonByUrl(currentUrl);
        recordYouTubeNavigation(currentUrl);
        const fallbackCover = getWebCoverFallbackByUrl(currentUrl);
        if (fallbackCover) {
            updateCoverArt(fallbackCover, 'web');
        }
        const key = getActiveAdblockCounterKey();
        if (key && key !== adblockRuntime.currentCounterKey) {
            adblockRuntime.currentCounterKey = key;
            adblockRuntime.counterBaseByKey.set(key, Number(adblockRuntime.lastAbsoluteBlocked || 0));
            adblockRuntime.lastBlocked = 0;
            updateAdblockBadge(0);
        }
        console.log('[WEB] Navigation detected, resetting MPRIS position');
        state.webTrackId++; // Yeni bir ID atayarak sistemin "yeni parça" algılamasını sağla
        state.webPosition = 0;
        state.webDuration = 0;
        state.webTitle = '';
        state.webPendingTitle = '';
        state.webArtist = '';
        state.webAlbum = '';
        // Metadata güncellemesi ile süreyi 0'a çek
        updateMPRISMetadata();
        scheduleApplyWebDaliEngine('navigate', 120);
        scheduleApplyWebDaliEngineBurst('navigate', [0, 90, 220, 500, 1000, 2000, 3200]);
    }

    // Güvenlik sayfası URL farkındadır
    if (isSecuritySettingsVisible()) {
        updateSecurityUI();
    }
}

// MPRIS'e metadata gönder (Linux ortam oynatıcısı)
async function updateMPRISMetadata() {
    if (!window.aurivo || !window.aurivo.updateMPRISMetadata) return;

    // Süre ve pozisyon al
    let duration = 0;
    let position = 0;
    let title = 'Bilinmeyen';
    let artist = uiT('nowPlaying.unknownArtist', 'Unknown Artist');
    let album = '';
    let trackId = state.currentIndex;
    let canGoNext = true;
    let canGoPrevious = true;
    let canSeek = true;

    if (state.activeMedia === 'video') {
        // Video için metadata
        const video = elements.videoPlayer;
        if (video && video.src) {
            duration = video.duration || 0; // saniye
            position = video.currentTime || 0; // saniye

            // Video dosya adından başlık çıkar
            const fileName = window.aurivo?.path?.basename?.(state.currentVideoPath || '') || video.src.split('/').pop().split('#')[0].split('?')[0];
            title = decodeURIComponent(String(fileName || '')).replace(/\.[^/.]+$/, '') || 'Video';
            artist = 'Video';
            // DÜZELTME: DBus objectPath için '-' gibi karakterler sorun çıkarabilir; güvenli parçaId üret.
            trackId = `video_${Math.max(0, Number(state.currentVideoIndex) || 0)}`;
            canGoNext = state.videoFiles.length > 1 && state.currentVideoIndex < state.videoFiles.length - 1;
            canGoPrevious = state.videoFiles.length > 1 && state.currentVideoIndex > 0;
        }
    } else if (state.activeMedia === 'audio') {
        // Ses için metadata
        const currentTrack = state.playlist[state.currentIndex];
        if (!currentTrack) return;

        // Dosya adından metadata çıkar
        const fileName = currentTrack.name || '';
        title = currentTrack.title || fileName.replace(/\.[^/.]+$/, ''); // Uzantıyı kaldır
        artist = currentTrack.artist || uiT('nowPlaying.unknownArtist', 'Unknown Artist');
        album = currentTrack.album || '';

        // Eğer title yoksa dosya adından parse et
        if (!currentTrack.title && fileName.includes(' - ')) {
            const parts = fileName.split(' - ');
            if (parts.length >= 2) {
                artist = parts[0].trim();
                title = parts[1].replace(/\.[^/.]+$/, '').trim();
            }
        }

        if (useNativeAudio && window.aurivo?.audio) {
            try {
                // getDuration saniye döndürür, getPosition milisaniye
                duration = await window.aurivo.audio.getDuration(); // saniye
                position = (await window.aurivo.audio.getPosition()) / 1000; // ms -> saniye
            } catch (e) {
                // yoksay
            }
        } else {
            const activePlayer = getActiveAudioPlayer();
            duration = activePlayer.duration || 0; // saniye
            position = activePlayer.currentTime || 0; // saniye
        }
        canGoNext = state.playlist.length > 0 && state.currentIndex < state.playlist.length - 1;
        canGoPrevious = state.playlist.length > 0 && state.currentIndex > 0;
    } else if (state.activeMedia === 'web') {
        title = state.webTitle || state.webPendingTitle || elements.nowPlayingLabel.textContent.replace(`${uiT('nowPlaying.prefix', 'Now Playing')}: `, '') || uiT('web.media', 'Web Media');
        artist = state.webArtist || 'Aurivo Web';
        album = state.webAlbum || 'Online';
        trackId = `web_${state.webTrackId}`; // DÜZELTME: Daha güvenli DBus yolu için tire alt çizgiyle değiştirildi
        duration = state.webDuration || 0;
        position = state.webPosition || 0;
        // Web platformlarında ileri/geri komutlarını JS ile yönlendirdiğimiz için etkin bırak.
        canGoNext = true;
        canGoPrevious = true;
        canSeek = true;
    }

    window.aurivo.updateMPRISMetadata({
        trackId: trackId,
        title: title,
        artist: artist,
        album: album,
        albumArt: state.currentCover || '',
        duration: duration,
        position: position,
        isPlaying: state.isPlaying,
        canGoNext,
        canGoPrevious,
        canSeek
    });
}

// Web/YouTube senkronizasyon işleyicisi
function handleWebSync(data) {
    if (state.activeMedia !== 'web') return;
    const syncEligible = data?.syncEligible !== false;

    if (data.type === 'pending-title') {
        const hint = String(data.title || '').trim();
        if (hint) {
            state.webPendingTitle = hint;
            if (elements.nowPlayingLabel) {
                elements.nowPlayingLabel.textContent = `${uiT('nowPlaying.prefix', 'Now Playing')}: ${hint}`;
            }
            updateTrayState();
            updateMPRISMetadata();
        }
        return;
    }

    if (data.type === 'metadata') {
        if (!syncEligible) return;
        state.webTitle = data.title || '';
        if (state.webTitle) state.webPendingTitle = '';
        state.webArtist = data.artist || '';
        state.webAlbum = data.album || '';

        if (state.webTitle) elements.nowPlayingLabel.textContent = `${uiT('nowPlaying.prefix', 'Now Playing')}: ${state.webTitle}`;
        const currentUrl = getWebViewUrlSafe();
        const ytFallbackCover = getWebCoverFallbackByUrl(currentUrl);
        // YouTube'da mediaSession artwork bazen reklam/yan akış görseli döndürebilir.
        // Aktif video URL'sinden üretilen kapak önceliklidir.
        if (ytFallbackCover) {
            updateCoverArt(ytFallbackCover, 'web');
        } else if (data.artwork) {
            updateCoverArt(data.artwork, 'web');
        }

        updateTrayState();
        updateMPRISMetadata();
        return;
    }

    if (data.type === 'volume') {
        applyWebVolumeToUi(data.volume, data.muted);
        return;
    }

    if (!syncEligible) return;

    state.webPosition = data.currentTime || 0;
    state.webDuration = data.duration || 0;

    // timeupdate yükü duraklatma durumunu taşıyabilir (yoklama)
    if (data.type === 'timeupdate' && typeof data.paused === 'boolean') {
        const nextPlaying = !data.paused;
        if (state.isPlaying !== nextPlaying) {
            state.isPlaying = nextPlaying;
            updatePlayPauseIcon(nextPlaying);
            updateTrayState();
            updateMPRISMetadata();
        }
    }

    if (data.type === 'play') {
        state.isPlaying = true;
        updatePlayPauseIcon(true);
        updateTrayState();
        updateMPRISMetadata();
    } else if (data.type === 'pause') {
        state.isPlaying = false;
        updatePlayPauseIcon(false);
        updateTrayState();
        updateMPRISMetadata();
        scheduleRememberPlaybackStartupState(220);
    } else if (data.type === 'seeked' || data.type === 'durationchange' || data.type === 'loadeddata') {
        updateMPRISMetadata();
    }

    // UI Güncelleme (Süre ve Slider)
    if (elements.currentTime && elements.durationTime) {
        elements.currentTime.textContent = formatTime(state.webPosition);
        elements.durationTime.textContent = formatTime(state.webDuration);
    }
    if (elements.seekSlider && state.webDuration > 0) {
        const progress = (state.webPosition / state.webDuration) * 1000;
        elements.seekSlider.value = progress;
        updateRainbowSlider(elements.seekSlider, progress / 10);
    }

}

function pushAppVolumeToWeb() {
    if (state.activeMedia !== 'web' || !elements.webView) return;

    const vol = Math.max(0, Math.min(100, Number(state.volume) || 0));
    const muted = !!state.isMuted || vol === 0;
    const target = Math.max(0, Math.min(1, vol / 100));

    const now = Date.now();
    webVolumeSync.lastPushAt = now;
    webVolumeSync.lastPushedPercent = vol;
    webVolumeSync.lastPushedMuted = muted;
    webVolumeSync.ignoreIncomingUntil = now + 850;
    elements.webView.executeJavaScript(`
        (function() {
            const volPct = ${vol};
            const wantMuted = ${muted ? 'true' : 'false'};
            const targetLinear = ${target};
            const root = window.__AURIVO_DALI_WEB__;
            const hasRuntimeMaster = !!(root && typeof root.setRuntimeMasterVolume === 'function');

            // YouTube player API varsa klasik yol:
            // DALI runtime master yoksa doğrudan web player volume/mute kontrolü.
            const yt = document.getElementById('movie_player');
            if (!hasRuntimeMaster && yt && typeof yt.setVolume === 'function') {
                try { yt.setVolume(volPct); } catch (e) {}
                try {
                    if (wantMuted) {
                        if (typeof yt.mute === 'function') yt.mute();
                    } else {
                        if (typeof yt.unMute === 'function') yt.unMute();
                    }
                } catch (e) {}
            }

            const m = document.querySelector('video.html5-main-video, video, audio');
            if (!m) return false;
            if (hasRuntimeMaster) {
                // Web görselleştirme için saf sinyalin akmaya devam etmesi gerekir.
                // Bu yüzden element volume/mute yerine sadece runtime master gain ile kıs.
                try { root.setRuntimeMasterVolume(targetLinear, wantMuted); } catch (e) {}
                try {
                    m.muted = false;
                    if (!Number.isFinite(Number(m.volume)) || Number(m.volume) <= 0.0001) {
                        m.volume = 1;
                    }
                } catch (e) {}
                return true;
            }
            m.volume = targetLinear;
            m.muted = wantMuted;
            return true;
        })();
    `).catch(() => {
        // yoksay
    });
}

function shouldAcceptIncomingWebVolume(percent, muted) {
    const safePercent = Math.max(0, Math.min(100, Number(percent) || 0));
    const now = Date.now();
    if (now < Number(webVolumeSync.ignoreIncomingUntil || 0)) return false;

    // Web tarafındaki kullanıcı etkileşimini (YouTube/diğer platform slider'ı)
    // engellememek için yalnızca kısa "echo" penceresinde blokla.
    return true;
}

function applyWebVolumeToUi(rawVolume, rawMuted) {
    const volume01 = Math.max(0, Math.min(1, Number(rawVolume) || 0));
    const percent = Math.round(volume01 * 100);
    const muted = !!rawMuted || percent === 0;
    if (!shouldAcceptIncomingWebVolume(percent, muted)) {
        // App -> web echo penceresinde gelen geri bildirimleri yoksay.
        return;
    }

    state.volume = percent;
    state.isMuted = muted;
    if (!muted) state.savedVolume = percent;

    if (elements.volumeSlider) {
        elements.volumeSlider.value = percent;
        updateRainbowSlider(elements.volumeSlider, percent);
    }
    if (elements.volumeLabel) elements.volumeLabel.textContent = `${percent}%`;
    updateAudioAppVolumeUi(percent);

    const fsVolumeSlider = document.getElementById('fsVolumeSlider');
    const fsVolumeLabel = document.getElementById('fsVolumeLabel');
    if (fsVolumeSlider) {
        fsVolumeSlider.value = percent;
        updateRainbowSlider(fsVolumeSlider, percent);
    }
    if (fsVolumeLabel) fsVolumeLabel.textContent = `${percent}%`;

    updateVolumeIcon();
    updateFsVolumeIcon();
}

function setupDragAndDrop() {
    const dropZone = elements.playlist;
    const appDropTargets = [
        window,
        document,
        document.documentElement,
        document.body,
        document.querySelector('.main-content'),
        document.querySelector('.content-stack'),
        elements.musicPage
    ].filter(Boolean);

    const addDropListener = (target, eventName, handler, options) => {
        try {
            target.addEventListener(eventName, handler, options);
        } catch {
            target.addEventListener(eventName, handler, !!(options && options.capture));
        }
    };

    // Varsayılan sürükleme davranışlarını engelle
    ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
        if (dropZone) dropZone.addEventListener(eventName, preventDefaults, false);
        appDropTargets.forEach((target) => {
            addDropListener(target, eventName, preventDefaults, { capture: true, passive: false });
        });
    });

    // Öğe üzerine sürüklendiğinde bırakma alanını vurgula
    ['dragenter', 'dragover'].forEach(eventName => {
        if (dropZone) {
            dropZone.addEventListener(eventName, (e) => {
                if (isInternalPlaylistReorderEvent(e)) return;
                dropZone.classList.add('drag-over');
            }, false);
        }
    });

    ['dragleave', 'drop'].forEach(eventName => {
        if (dropZone) {
            dropZone.addEventListener(eventName, (e) => {
                if (isInternalPlaylistReorderEvent(e)) return;
                dropZone.classList.remove('drag-over');
            }, false);
        }
    });

    // Bırakılan dosyaları uygulama genelinde yakala (orta alan dahil)
    appDropTargets.forEach((target) => {
        addDropListener(target, 'drop', handleFileDrop, { capture: true, passive: false });
    });
}

function getInternalReorderDragGhost() {
    if (internalReorderDragGhost) return internalReorderDragGhost;
    const ghost = document.createElement('canvas');
    ghost.width = 1;
    ghost.height = 1;
    internalReorderDragGhost = ghost;
    return ghost;
}

// Ağaç öğesi sürükleme başlangıcı
function handleTreeItemDragStart(e) {
    // Seçili tüm dosyaları al
    const selectedItems = document.querySelectorAll('.tree-item.file.selected');

    // Eğer sürüklenen öğe seçili değilse, sadece onu seç
    if (!e.target.closest('.tree-item').classList.contains('selected')) {
        document.querySelectorAll('.tree-item.file').forEach(i => i.classList.remove('selected'));
        e.target.closest('.tree-item').classList.add('selected');
    }

    // Seçili dosya yollarını JSON olarak aktar
    const filePaths = [];
    document.querySelectorAll('.tree-item.file.selected').forEach(item => {
        filePaths.push({
            path: item.dataset.path,
            name: item.dataset.name
        });
    });

    e.dataTransfer.setData('text/aurivo-files', JSON.stringify(filePaths));
    e.dataTransfer.effectAllowed = 'copy';

    // Sürükleme görselini ayarla
    e.target.closest('.tree-item').classList.add('dragging');
}

// Ağaç öğesi sürükleme bitişi
function handleTreeItemDragEnd(e) {
    e.target.closest('.tree-item').classList.remove('dragging');
}

function preventDefaults(e) {
    if (isInternalPlaylistReorderEvent(e)) {
        e.preventDefault();
        try {
            if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
        } catch {
            // yoksay
        }
        return;
    }
    e.preventDefault();
    e.stopPropagation();
    try {
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    } catch {
        // yoksay
    }
}

function isInternalPlaylistReorderEvent(e) {
    try {
        const types = Array.from(e?.dataTransfer?.types || []);
        if (types.includes('text/aurivo-reorder')) return true;
    } catch {
        // yoksay
    }

    const target = e?.target;
    if (target instanceof HTMLElement && target.closest('.playlist-item.queue-draggable-item')) {
        return true;
    }
    return false;
}

// ============================================
// SES OYNATICI OLAY KURULUMU
// ============================================
function setupAudioPlayerEvents(player, playerId) {
    // Zaman güncelleme
    player.addEventListener('timeupdate', () => {
        // Native ses kullanıyorken HTML5 audio event'lerini tamamen devre dışı bırak
        if (useNativeAudio) return;

        // Sadece aktif oynatıcı için güncelle
        if (getActiveAudioPlayer() === player) {
            updateTimeDisplay();
            // Otomatik çapraz geçiş kontrolü
            maybeStartAutoCrossfade();
            const sec = Math.floor(Number(player.currentTime) || 0);
            if (sec >= 0 && sec % 8 === 0 && sec !== state.playbackStatePersistSecond) {
                state.playbackStatePersistSecond = sec;
                scheduleRememberPlaybackStartupState(260);
            }
        }
    });

    // Metadata yüklendiğinde
    player.addEventListener('loadedmetadata', () => {
        // Native ses kullanıyorken HTML5 audio event'lerini tamamen devre dışı bırak
        if (useNativeAudio) return;

        if (getActiveAudioPlayer() === player) {
            handleMetadataLoaded();
        }
    });

    // Parça bittiğinde
    player.addEventListener('ended', () => {
        // Native ses kullanıyorken HTML5 audio event'lerini tamamen devre dışı bırak
        if (useNativeAudio) return;

        if (getActiveAudioPlayer() === player) {
            handleTrackEnded();
        }
    });

    // Play/Pause durumu
    player.addEventListener('play', () => {
        // Native ses kullanıyorken HTML5 audio event'lerini tamamen devre dışı bırak
        if (useNativeAudio) return;

        if (getActiveAudioPlayer() === player) {
            updatePlayPauseIcon(true);
        }
    });

    player.addEventListener('pause', () => {
        // Native ses kullanıyorken HTML5 audio event'lerini tamamen devre dışı bırak
        if (useNativeAudio) return;

        if (getActiveAudioPlayer() === player) {
            updatePlayPauseIcon(false);
        }
    });
}

// Video Oynatıcı Olay Dinleyicileri
function setupVideoPlayerEvents() {
    const video = elements.videoPlayer;
    if (!video) return;

    // Zaman güncelleme
    video.addEventListener('timeupdate', () => {
        if (state.activeMedia === 'video') {
            updateTimeDisplay();

            // MPRIS position'ını sınırla (her 2 saniyede bir)
            const currentSecInt = Math.floor(video.currentTime || 0);
            if (currentSecInt !== state.lastMPRISPosition && currentSecInt % 2 === 0) {
                state.lastMPRISPosition = currentSecInt;
                updateMPRISMetadata();
            }
        }
    });

    // Metadata yüklendiğinde
    video.addEventListener('loadedmetadata', () => {
        if (state.activeMedia === 'video') {
            updateTimeDisplay();
            updateMPRISMetadata();
            // Video metadata hazır olduğunda DSP grafiğini güvenli şekilde uygula.
            scheduleApplyWebDaliEngine('video-metadata', 40);
        }
    });

    // Video bittiğinde
    video.addEventListener('ended', () => {
        if (state.activeMedia === 'video') {
            state.isPlaying = false;
            updatePlayPauseIcon(false);
            renderVideoLibraryTree();
            updateTrayState();
            updateMPRISMetadata();

            // Sıradaki videoyu çal (kütüphaneden)
            playNextVideo();
        }
    });

    // Play/Pause durumu
    video.addEventListener('play', () => {
        if (state.activeMedia === 'video') {
            state.isPlaying = true;
            updatePlayPauseIcon(true);
            renderVideoLibraryTree();
            updateTrayState();
            updateMPRISMetadata();
            // Oynatma başladığında efekt zincirini aktif videoya yeniden uygula.
            scheduleApplyWebDaliEngine('video-play', 20);
        }
    });

    video.addEventListener('pause', () => {
        if (state.activeMedia === 'video') {
            state.isPlaying = false;
            updatePlayPauseIcon(false);
            renderVideoLibraryTree();
            updateTrayState();
            updateMPRISMetadata();
        }
    });
}

async function requestFullscreenSafe(el) {
    if (!el) return false;
    try {
        if (typeof el.requestFullscreen === 'function') {
            await el.requestFullscreen();
            return true;
        }
    } catch { }
    try {
        if (typeof el.webkitRequestFullscreen === 'function') {
            el.webkitRequestFullscreen();
            return true;
        }
    } catch { }
    try {
        if (typeof el.mozRequestFullScreen === 'function') {
            el.mozRequestFullScreen();
            return true;
        }
    } catch { }
    return false;
}

function exitFullscreenSafe() {
    try {
        if (typeof document.exitFullscreen === 'function') {
            document.exitFullscreen();
            return true;
        }
    } catch { }
    try {
        if (typeof document.webkitExitFullscreen === 'function') {
            document.webkitExitFullscreen();
            return true;
        }
    } catch { }
    try {
        if (typeof document.mozCancelFullScreen === 'function') {
            document.mozCancelFullScreen();
            return true;
        }
    } catch { }
    return false;
}

async function syncWindowFullscreenState() {
    try {
        const api = window.aurivo?.electronAPI;
        if (api && typeof api.isFullscreen === 'function') {
            fsWindowFullscreenActive = !!(await api.isFullscreen());
        }
    } catch {
        // yoksay
    }
    return fsWindowFullscreenActive;
}

async function setWindowFullscreenSafe(enabled) {
    try {
        const api = window.aurivo?.electronAPI;
        if (api && typeof api.setFullscreen === 'function') {
            fsWindowFullscreenActive = !!(await api.setFullscreen(!!enabled));
            return true;
        }
    } catch {
        // yoksay
    }
    return false;
}

async function toggleWindowFullscreenSafe() {
    try {
        const api = window.aurivo?.electronAPI;
        if (api && typeof api.toggleFullscreen === 'function') {
            fsWindowFullscreenActive = !!(await api.toggleFullscreen());
            return true;
        }
    } catch {
        // yoksay
    }
    return false;
}

function ensureWindowFullscreenBridge() {
    if (fsWindowFullscreenHooked) return;
    const api = window.aurivo?.electronAPI;
    if (!api || typeof api.onFullscreenChanged !== 'function') return;

    fsWindowFullscreenUnsubscribe = api.onFullscreenChanged((isFullscreen) => {
        fsWindowFullscreenActive = !!isFullscreen;
        handleFullscreenChange();
    });
    fsWindowFullscreenHooked = true;
    syncWindowFullscreenState()
        .then(() => handleFullscreenChange())
        .catch(() => { /* yoksay */ });
}

function getDomFullscreenElement() {
    return (
        document.fullscreenElement ||
        document.webkitFullscreenElement ||
        document.mozFullScreenElement
    );
}

async function toggleVideoFullscreenCore(targetEnter, videoPage) {
    if (targetEnter) {
        // Electron penceresi için en kararlı yol.
        await setWindowFullscreenSafe(true);
        await syncWindowFullscreenState();
        let ok = fsWindowFullscreenActive;

        // WM/Platform farkları için DOM fullscreen fallback.
        if (!ok) ok = await requestFullscreenSafe(videoPage);
        if (!ok && elements.videoPlayer) ok = await requestFullscreenSafe(elements.videoPlayer);
        if (!ok) {
            await toggleWindowFullscreenSafe();
            await syncWindowFullscreenState();
        }
        return;
    }

    const activeEl = getDomFullscreenElement();
    if (activeEl) {
        exitFullscreenSafe();
    } else {
        await setWindowFullscreenSafe(false);
    }
    await syncWindowFullscreenState();
}

async function toggleVideoFullscreenLegacy(targetEnter, videoPage) {
    if (targetEnter) {
        let ok = await requestFullscreenSafe(videoPage);
        if (!ok && elements.videoPlayer) ok = await requestFullscreenSafe(elements.videoPlayer);
        if (!ok) await setWindowFullscreenSafe(true);
    } else {
        const activeEl = getDomFullscreenElement();
        if (activeEl) exitFullscreenSafe();
        else await setWindowFullscreenSafe(false);
    }
    await syncWindowFullscreenState();
}

async function toggleVideoFullscreen() {
    const now = Date.now();
    if (videoFullscreenToggleInFlight) return;
    if (now - videoFullscreenLastToggleAt < 160) return;
    videoFullscreenToggleInFlight = true;

    const videoPage = document.getElementById('videoPage');
    if (!videoPage) {
        videoFullscreenToggleInFlight = false;
        return;
    }

    const wasFullscreen = isVideoFullscreenActive();
    const targetEnter = !wasFullscreen;

    try {
        if (videoFullscreenFlowState.useLegacy) {
            await toggleVideoFullscreenLegacy(targetEnter, videoPage);
        } else {
            await toggleVideoFullscreenCore(targetEnter, videoPage);
        }

        await syncWindowFullscreenState();
        const nowFullscreen = isVideoFullscreenActive();
        const reachedTarget = targetEnter ? nowFullscreen : !nowFullscreen;

        if (!reachedTarget) {
            videoFullscreenFlowState.consecutiveFailures += 1;
            console.warn('[VIDEO-FS] toggle target not reached, retrying with legacy path');
            await toggleVideoFullscreenLegacy(targetEnter, videoPage);
            await syncWindowFullscreenState();

            const afterLegacy = isVideoFullscreenActive();
            const legacyReached = targetEnter ? afterLegacy : !afterLegacy;
            if (!legacyReached) {
                videoFullscreenFlowState.consecutiveFailures += 1;
            } else {
                videoFullscreenFlowState.consecutiveFailures = 0;
            }
        } else {
            videoFullscreenFlowState.consecutiveFailures = 0;
        }

        if (!videoFullscreenFlowState.useLegacy && videoFullscreenFlowState.consecutiveFailures >= videoFullscreenFlowState.maxFailuresBeforeLegacy) {
            videoFullscreenFlowState.useLegacy = true;
            console.warn('[VIDEO-FS] switched to legacy fullscreen path');
        }
    } catch (e) {
        videoFullscreenFlowState.consecutiveFailures += 1;
        if (!videoFullscreenFlowState.useLegacy) {
            try {
                await toggleVideoFullscreenLegacy(targetEnter, videoPage);
                await syncWindowFullscreenState();
            } catch {
                // yoksay
            }
        }
        if (videoFullscreenFlowState.consecutiveFailures >= videoFullscreenFlowState.maxFailuresBeforeLegacy) {
            videoFullscreenFlowState.useLegacy = true;
        }
        console.warn('[VIDEO-FS] toggle error:', e?.message || e);
    } finally {
        videoFullscreenLastToggleAt = Date.now();
        videoFullscreenToggleInFlight = false;
        syncWindowFullscreenLayoutState();
    }
}

function isVideoSurfaceTarget(target) {
    if (!target || !(target instanceof Element)) return false;
    if (!target.closest('#videoPage, #videoPlayer')) return false;
    if (target.closest('#videoFsControls, .context-menu, button, input, select, textarea, [role=\"button\"]')) return false;
    return true;
}

function handleVideoSurfaceDoubleClick(e) {
    if (e?.__aurivoVideoFsHandled) return;
    if (e) e.__aurivoVideoFsHandled = true;
    const target = e?.target;
    if (!target || !(target instanceof Element)) {
        toggleVideoFullscreen();
        return;
    }
    if (!isVideoSurfaceTarget(target)) return;
    toggleVideoFullscreen();
}

function handleGlobalVideoDoubleClickCapture(e) {
    if (!isPageVisible(elements.videoPage)) return;
    const target = e?.target;
    if (isVideoSurfaceTarget(target)) {
        handleVideoSurfaceDoubleClick(e);
        return;
    }

    // Overlay/üst katman video üstünde ise target videoPage altında olmayabilir.
    // Bu durumda koordinata göre video alanında çift tıkı kabul et.
    const videoPage = document.getElementById('videoPage');
    if (!videoPage) return;
    if (typeof e?.clientX !== 'number' || typeof e?.clientY !== 'number') return;
    const rect = videoPage.getBoundingClientRect();
    const insideVideoRect =
        e.clientX >= rect.left && e.clientX <= rect.right &&
        e.clientY >= rect.top && e.clientY <= rect.bottom;
    if (!insideVideoRect) return;

    if (target instanceof Element) {
        if (target.closest('#videoFsControls, .context-menu, .sidebar, .left-panel, .nav-bar, .player-bar, button, input, select, textarea, [role=\"button\"]')) {
            return;
        }
    }
    handleVideoSurfaceDoubleClick(e);
}

function handleVideoSurfaceMouseUpFallback(e) {
    if ((e?.detail || 0) < 2) return;
    if (!isVideoSurfaceTarget(e?.target)) return;
    handleVideoSurfaceDoubleClick(e);
}

